Clase Vehiculo
    Privado Definir ruedas Como Entero;

    Metodo Constructor(unasRuedas Como Entero)
        Este.ruedas <- unasRuedas;
    FinMetodo

    Publico Metodo Ruedas() Como Entero
        Retornar Este.ruedas;
    FinMetodo
FinClase

Clase Motocicleta Hereda De Vehiculo
    Metodo Constructor()
        Super.Constructor(2);
    FinMetodo
FinClase

Clase Automovil Hereda De Vehiculo
    Metodo Constructor()
        Super.Constructor(4);
    FinMetodo
FinClase

Proceso ContarRuedas
    Definir tipo Como Entero;
    Definir vehiculo Como Vehiculo;
    Leer tipo;
    Si tipo = 1 Entonces
        vehiculo <- Nuevo Motocicleta();
    SiNo
        vehiculo <- Nuevo Automovil();
    FinSi
    Escribir vehiculo.Ruedas();
FinProceso
